import{_ as i,o as t,c as a,a5 as e}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"916-不同文件夹下同名pdf文件按选择文件夹顺序合并为一个pdf","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-19T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["PDF批处理"],"标签":["PDF工具","PDF文件合并","Python GUI程序","办公效率工具","办公自动化工具","同名文件合并","批量PDF处理","文件合并软件","文件夹管理","文档批处理"]},"headers":[{"level":3,"title":"功能特点","slug":"功能特点","link":"#功能特点","children":[]},{"level":3,"title":"程序截图","slug":"程序截图","link":"#程序截图","children":[]},{"level":3,"title":"详细使用说明","slug":"详细使用说明","link":"#详细使用说明","children":[{"level":4,"title":"文件夹管理","slug":"文件夹管理","link":"#文件夹管理","children":[]},{"level":4,"title":"输出设置","slug":"输出设置","link":"#输出设置","children":[]},{"level":4,"title":"合并操作","slug":"合并操作","link":"#合并操作","children":[]},{"level":4,"title":"日志系统","slug":"日志系统","link":"#日志系统","children":[]}]},{"level":3,"title":"使用场景示例","slug":"使用场景示例","link":"#使用场景示例","children":[{"level":4,"title":"场景一：合并多版本合同文件","slug":"场景一-合并多版本合同文件","link":"#场景一-合并多版本合同文件","children":[]},{"level":4,"title":"场景二：整合教学资料","slug":"场景二-整合教学资料","link":"#场景二-整合教学资料","children":[]},{"level":4,"title":"场景三：合并项目文档","slug":"场景三-合并项目文档","link":"#场景三-合并项目文档","children":[]}]},{"level":3,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":3,"title":"常见问题解答","slug":"常见问题解答","link":"#常见问题解答","children":[]},{"level":3,"title":"程序使用环境及相关说明","slug":"程序使用环境及相关说明","link":"#程序使用环境及相关说明","children":[]},{"level":3,"title":"程序使用说明","slug":"程序使用说明","link":"#程序使用说明","children":[]}],"relativePath":"md/PDF批处理/916-不同文件夹下同名pdf文件按选择文件夹顺序合并为一个pdf.md","filePath":"md/PDF批处理/916-不同文件夹下同名pdf文件按选择文件夹顺序合并为一个pdf.md"}'),r={name:"md/PDF批处理/916-不同文件夹下同名pdf文件按选择文件夹顺序合并为一个pdf.md"};function n(o,l,s,h,g,d){return t(),a("div",null,[...l[0]||(l[0]=[e('<p>用于处理不同文件夹下同名PDF文件的合并任务，有多个文件夹，每个文件夹下有多个pdf文件，将不同文件夹下名称相同的pdf合并保存到目标文件夹下。</p><p>可以选择多个文件夹（文件夹可以拖入到文件夹列表）方便快捷，按照指定的顺序将同名PDF文件合并为一个PDF文件。</p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><ul><li>智能同名文件识别：自动扫描多个文件夹，识别相同文件名的PDF文件进行合并</li><li>拖拽式操作：支持直接拖拽文件夹到界面进行添加，操作简便快捷</li><li>灵活的文件夹排序：可以通过上移、下移按钮调整文件夹顺序，控制合并顺序</li><li><strong>实时日志显示</strong>：在处理过程中实时显示操作日志，包括成功、错误和信息提示</li><li><strong>多线程处理</strong>：采用独立线程执行合并任务，避免界面卡顿</li><li><strong>自定义输出路径</strong>：用户可自由选择合并后PDF文件的保存位置</li><li><strong>完善的错误处理</strong>：对各种异常情况进行捕获和处理，提供友好的错误提示</li></ul><h3 id="程序截图" tabindex="-1">程序截图 <a class="header-anchor" href="#程序截图" aria-label="Permalink to &quot;程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260311101453177319529342305-1.png" alt=""></p><h3 id="详细使用说明" tabindex="-1">详细使用说明 <a class="header-anchor" href="#详细使用说明" aria-label="Permalink to &quot;详细使用说明&quot;">​</a></h3><h4 id="文件夹管理" tabindex="-1">文件夹管理 <a class="header-anchor" href="#文件夹管理" aria-label="Permalink to &quot;文件夹管理&quot;">​</a></h4><ul><li><strong>添加文件夹</strong>：点击”➕ 添加文件夹”按钮，在弹出的对话框中选择要添加的文件夹。也可以直接将文件夹拖拽到列表区域。</li><li><strong>删除文件夹</strong>：在列表中选中要删除的文件夹，点击”🗑 删除选中”按钮。</li><li><strong>调整顺序</strong>：选中文件夹后，使用”⬆ 上移”和”⬇ 下移”按钮调整文件夹的顺序。合并时将按照列表中的顺序依次处理同名PDF文件。</li></ul><h4 id="输出设置" tabindex="-1">输出设置 <a class="header-anchor" href="#输出设置" aria-label="Permalink to &quot;输出设置&quot;">​</a></h4><ul><li><strong>选择输出路径</strong>：点击”浏览…”按钮，在弹出的对话框中选择合并后PDF文件的保存位置。也可以直接拖拽文件夹到输出路径区域。</li><li><strong>输出路径显示</strong>：选定的输出路径会显示在”合并后保存路径”输入框中。</li></ul><h4 id="合并操作" tabindex="-1">合并操作 <a class="header-anchor" href="#合并操作" aria-label="Permalink to &quot;合并操作&quot;">​</a></h4><ul><li><strong>开始合并</strong>：确保已添加至少2个文件夹并设置了输出路径后，点击”开始合并PDF”按钮。</li><li><strong>处理过程</strong>：程序会在独立线程中执行合并任务，界面不会卡顿。日志区域会实时显示处理进度。</li><li><strong>清除日志</strong>：点击”🧹 清除日志”按钮可以清空日志区域的内容。</li></ul><h4 id="日志系统" tabindex="-1">日志系统 <a class="header-anchor" href="#日志系统" aria-label="Permalink to &quot;日志系统&quot;">​</a></h4><ul><li><strong>日志类型</strong>： <ul><li>蓝色文本：一般信息提示</li><li>绿色文本：操作成功提示</li><li>红色文本：错误和警告信息</li></ul></li><li><strong>实时更新</strong>：日志会自动滚动到最新内容，方便用户查看处理进度。</li></ul><h3 id="使用场景示例" tabindex="-1">使用场景示例 <a class="header-anchor" href="#使用场景示例" aria-label="Permalink to &quot;使用场景示例&quot;">​</a></h3><h4 id="场景一-合并多版本合同文件" tabindex="-1">场景一：合并多版本合同文件 <a class="header-anchor" href="#场景一-合并多版本合同文件" aria-label="Permalink to &quot;场景一：合并多版本合同文件&quot;">​</a></h4><p>某公司需要将不同部门保存的合同文件进行整理。每个部门都有独立的文件夹，文件夹中包含相同名称的合同PDF文件，但内容是不同版本或补充材料。使用本工具：</p><ol><li>添加所有部门文件夹到列表中</li><li>按照合同版本顺序调整文件夹顺序</li><li>选择输出文件夹为”合并后合同”文件夹</li><li>点击”开始合并PDF”按钮</li><li>程序自动将同名合同文件合并为一个PDF，保存到输出文件夹</li></ol><h4 id="场景二-整合教学资料" tabindex="-1">场景二：整合教学资料 <a class="header-anchor" href="#场景二-整合教学资料" aria-label="Permalink to &quot;场景二：整合教学资料&quot;">​</a></h4><p>一位教师需要将不同学期的教学资料进行整合。每个学期的资料保存在独立文件夹中，相同课程名称的PDF文件需要合并。使用本工具：</p><ol><li>将各学期文件夹拖拽到列表区域</li><li>按照学期顺序调整文件夹排列</li><li>选择输出文件夹为”整合后资料”文件夹</li><li>点击”开始合并PDF”按钮</li><li>程序将同名课程PDF文件按学期顺序合并，方便教学使用</li></ol><h4 id="场景三-合并项目文档" tabindex="-1">场景三：合并项目文档 <a class="header-anchor" href="#场景三-合并项目文档" aria-label="Permalink to &quot;场景三：合并项目文档&quot;">​</a></h4><p>一个项目团队需要将不同成员提交的项目文档进行汇总。每个成员的文档保存在独立文件夹中，相同文档名称的PDF需要合并。使用本工具：</p><ol><li>添加所有团队成员文件夹</li><li>按照文档提交顺序调整文件夹顺序</li><li>选择输出文件夹为”项目汇总”文件夹</li><li>点击”开始合并PDF”按钮</li><li>程序自动合并同名项目文档，生成完整的汇总文档</li></ol><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>至少需要2个文件夹：程序要求至少添加2个文件夹才能执行合并操作，否则会提示错误。</li><li>必须设置输出路径：在开始合并前必须选择输出文件夹，否则无法执行合并操作。</li><li>文件覆盖风险：如果输出文件夹中已存在同名文件，合并操作会覆盖原文件，请确保输出路径正确。</li><li><strong>仅处理PDF文件</strong>：程序只会处理扩展名为.pdf的文件，其他格式的文件会被忽略。</li><li><strong>临时文件过滤</strong>：程序会自动跳过以”~$”或”.”开头的临时文件。</li><li><strong>文件夹权限</strong>：确保对源文件夹和输出文件夹都有读取和写入权限。</li><li><strong>处理时间</strong>：合并大量文件可能需要较长时间，请耐心等待处理完成。</li><li><strong>程序兼容性</strong>：建议在Windows系统上运行。</li></ul><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><p><strong>Q: 为什么点击”开始合并PDF”按钮没有反应？</strong></p><p>A: 请检查是否满足以下条件：</p><ol><li>是否已添加至少2个文件夹</li><li>是否已设置输出路径</li><li>是否有正在进行的合并任务<br> 如果以上条件都满足但仍有问题，请查看日志区域的错误提示。</li></ol><p><strong>Q: 合并后的PDF文件顺序不对怎么办？</strong></p><p>A: 合并顺序取决于文件夹在列表中的排列顺序。请使用”⬆ 上移”和”⬇ 下移”按钮调整文件夹顺序，然后重新执行合并操作。</p><p><strong>Q: 可以合并不同名称的PDF文件吗？</strong></p><p>A: 不可以。本工具专门用于合并同名PDF文件，不同名称的文件不会被合并。如果需要合并不同名称的文件，请先重命名文件使其名称一致。</p><p><strong>Q: 拖拽文件夹到界面没有反应怎么办？</strong></p><p>A: 请确保：</p><ol><li>拖拽的是文件夹而不是文件</li><li>文件夹没有被重复添加</li><li>程序没有正在执行合并任务<br> 如果问题持续存在，请尝试使用”➕ 添加文件夹”按钮手动添加。</li></ol><p><strong>Q: 合并过程中出现错误怎么办？</strong></p><p>A: 请查看日志区域的红色错误提示，根据错误信息进行相应处理。常见错误包括：</p><ol><li>文件被占用：关闭相关程序后重试</li><li>权限不足：检查文件夹读写权限</li><li>文件损坏：检查源PDF文件是否完整</li></ol><p><strong>Q: 程序需要联网才能使用吗？</strong></p><p>A: 不需要。程序下载后可以离线使用，所有功能都在本地执行，确保数据安全。</p><p><strong>Q: 支持哪些操作系统？</strong></p><p>A: 程序主要针对Windows系统开发，建议在Windows 7及以上版本上运行。</p><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>解压后直接使用即可，程序可以放在任意位置</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260311101934177319557415000.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2649.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2649.html</a></p>',55)])])}const u=i(r,[["render",n]]);export{c as __pageData,u as default};
